namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public List<int> Ratings { get; set; } = [];

    public double AverageRating => Ratings.Count > 0 ? Ratings.Average() : 0;
    public int RatingCount => Ratings.Count;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt",
            Steps = "1. Preheat oven to 475°F (245°C).\n2. Roll out dough on a floured surface.\n3. Spread crushed tomatoes evenly over dough.\n4. Tear mozzarella and distribute over sauce.\n5. Bake for 10-12 minutes until crust is golden.\n6. Top with fresh basil and a drizzle of olive oil.",
            Ratings = [5, 4, 5, 4, 5]
        },
        new()
        {
            Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
            Ingredients = "Spaghetti\nGuanciale or pancetta\nEggs\nPecorino Romano\nBlack pepper",
            Steps = "1. Cook spaghetti in salted boiling water until al dente.\n2. Crisp guanciale in a pan over medium heat.\n3. Whisk eggs with grated Pecorino and pepper.\n4. Toss hot pasta with guanciale, remove from heat.\n5. Quickly stir in egg mixture — the residual heat cooks the eggs.\n6. Serve immediately with extra Pecorino.",
            Ratings = [5, 5, 4]
        },
        new()
        {
            Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
            Ingredients = "Chicken breast\nYogurt\nGaram masala\nTurmeric\nCumin\nCrushed tomatoes\nHeavy cream\nGarlic\nGinger\nOnion",
            Steps = "1. Marinate chicken in yogurt, turmeric, and cumin for 1 hour.\n2. Grill or broil chicken until charred.\n3. Sauté onion, garlic, and ginger in a pan.\n4. Add garam masala and crushed tomatoes; simmer 15 minutes.\n5. Stir in cream and add cooked chicken.\n6. Simmer 10 minutes and serve over rice.",
            Ratings = [5, 4, 4, 5]
        },
        new()
        {
            Id = 4, Title = "Vegetable Samosas", Category = "Indian",
            Ingredients = "Potatoes\nGreen peas\nCumin seeds\nCoriander\nGaram masala\nPastry sheets\nOil for frying",
            Steps = "1. Boil and mash potatoes.\n2. Sauté cumin seeds, add peas, coriander, and garam masala.\n3. Mix with mashed potatoes and let cool.\n4. Cut pastry sheets into strips and form cones.\n5. Fill cones with potato mixture and seal edges.\n6. Deep fry at 350°F until golden brown.",
            Ratings = [4, 4, 5]
        },
        new()
        {
            Id = 5, Title = "Beef Tacos", Category = "Mexican",
            Ingredients = "Ground beef\nTaco shells\nLettuce\nTomato\nCheddar cheese\nSour cream\nChili powder\nCumin\nGarlic powder",
            Steps = "1. Brown ground beef in a skillet over medium-high heat.\n2. Add chili powder, cumin, and garlic powder; stir well.\n3. Warm taco shells in the oven.\n4. Fill shells with seasoned beef.\n5. Top with shredded lettuce, diced tomato, cheese, and sour cream.",
            Ratings = [4, 3, 4, 5, 4]
        },
        new()
        {
            Id = 6, Title = "Guacamole", Category = "Mexican",
            Ingredients = "Avocados\nLime juice\nCilantro\nRed onion\nJalapeño\nTomato\nSalt",
            Steps = "1. Halve and pit avocados; scoop flesh into a bowl.\n2. Mash to desired consistency.\n3. Stir in diced onion, tomato, jalapeño, and cilantro.\n4. Add lime juice and salt to taste.\n5. Serve immediately with tortilla chips.",
            Ratings = [5, 5, 5, 4]
        },
        new()
        {
            Id = 7, Title = "Chocolate Lava Cake", Category = "Desserts",
            Ingredients = "Dark chocolate\nButter\nEggs\nSugar\nFlour\nVanilla extract",
            Steps = "1. Preheat oven to 425°F (220°C). Grease ramekins.\n2. Melt chocolate and butter together.\n3. Whisk eggs and sugar until thick.\n4. Fold chocolate mixture into eggs; add flour and vanilla.\n5. Pour into ramekins and bake 12-14 minutes.\n6. Invert onto plates and serve immediately.",
            Ratings = [5, 5, 5, 5, 4]
        },
        new()
        {
            Id = 8, Title = "Tiramisu", Category = "Desserts",
            Ingredients = "Ladyfingers\nMascarpone cheese\nEspresso\nEggs\nSugar\nCocoa powder\nKahlúa (optional)",
            Steps = "1. Brew espresso and let cool; add Kahlúa if using.\n2. Whisk egg yolks with sugar until pale.\n3. Fold in mascarpone until smooth.\n4. Whip egg whites to stiff peaks; fold into mascarpone mixture.\n5. Dip ladyfingers briefly in espresso and layer in dish.\n6. Spread mascarpone cream over ladyfingers; repeat layers.\n7. Refrigerate 4 hours; dust with cocoa before serving.",
            Ratings = [5, 4, 5]
        }
    ];

    private int _nextId = 9;

    public List<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public List<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.Ratings.Add(stars);
        }
    }
}

@rendermode InteractiveServer
@using RecipeShare.Services

<div class="star-rating">
    <div class="stars">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span class="star @(star <= (hoverStar ?? 0) ? "hover" : "") @(star <= currentRating ? "filled" : "")"
                  @onclick="() => Rate(star)"
                  @onmouseover="() => hoverStar = star"
                  @onmouseout="() => hoverStar = null"
                  role="button"
                  title="Rate @star star@(star > 1 ? "s" : "")">
                ★
            </span>
        }
    </div>
    <span class="rating-info">
        @if (AverageRating > 0)
        {
            <text>@AverageRating.ToString("0.0") / 5 (@RatingCount ratings)</text>
        }
        else
        {
            <text>No ratings yet</text>
        }
    </span>
    @if (submitted)
    {
        <span class="rating-thanks">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public int RecipeId { get; set; }

    [Parameter]
    public double AverageRating { get; set; }

    [Parameter]
    public int RatingCount { get; set; }

    [Inject]
    private RecipeService RecipeService { get; set; } = default!;

    private int currentRating;
    private int? hoverStar;
    private bool submitted;

    private void Rate(int stars)
    {
        currentRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            AverageRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
        submitted = true;
    }
}

.star-rating {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    flex-wrap: wrap;
}

.stars {
    display: flex;
    gap: 0.15rem;
}

.star {
    font-size: 1.75rem;
    color: #ccc;
    cursor: pointer;
    transition: color 0.15s, transform 0.15s;
    user-select: none;
}

.star:hover,
.star.hover {
    color: #f0ad4e;
    transform: scale(1.15);
}

.star.filled {
    color: #f5c518;
}

.rating-info {
    font-size: 0.9rem;
    color: #666;
}

.rating-thanks {
    font-size: 0.85rem;
    color: #28a745;
    font-weight: 500;
}

